INSERT INTO public.assistant_articles (slug, title, audience, body, links, confirmed, published) VALUES
('freestyle-battles', 'Freestyle battles and challenges', 'artist',
 'The 1v1 Freestyle Battle queue lives on the Play page. To pick an opponent: 1. Open Battle challenges. 2. Find the artist and send a challenge. 3. When they accept, the matchup fills one of the 10 battle slots and the host can start it from the live stage. You can have one opponent at a time; when all 10 slots are full the queue is closed until the host resets the tournament. The challenged artist gets a popup and an inbox notification to accept or decline.',
 '[{"label":"Battle challenges","to":"/play/challenges"},{"label":"Play Arena","to":"/play"}]'::jsonb, true, true),
('join-arena-stage', 'Join the Play Arena and live stage', 'everyone',
 'The Play Arena is on the Play page. Live sessions and stages that are actually broadcasting appear on the Live page — tap one to join as a listener. If you are an artist or host and want to be on stage, open your own live from Go Live, or ask the host of a live room to bring you on stage. Only the host can add speakers to their stage.',
 '[{"label":"Play Arena","to":"/play"},{"label":"Live now","to":"/live"},{"label":"Go Live","to":"/go-live"}]'::jsonb, true, true),
('mic-audio-troubleshooting', 'Microphone and audio troubleshooting', 'everyone',
 'If you cannot hear a live room, tap the Enable sound button — phones block automatic sound until you tap. If your microphone is not working on stage: 1. Check the browser or app has microphone permission for Tunevio. 2. Use the mute control beside Leave stage to unmute yourself. 3. If you hear static or echo, leave the stage and rejoin, and check that no other tab or app is using your microphone. Audience members never have microphones connected — only stage speakers do.',
 '[{"label":"Live now","to":"/live"},{"label":"Go Live","to":"/go-live"}]'::jsonb, true, true),
('battle-voting', 'Voting in battles', 'everyone',
 'You must be signed in to vote, and each account gets one vote per battle. In song battles, voting opens only after both artists'' songs have finished playing — the vote button stays closed until then. In freestyle battles, voting closes when the battle timer ends and the winner is announced from the counted votes. If you cannot vote, check that you are signed in and that voting is actually open for that battle.',
 '[{"label":"Play Arena","to":"/play"},{"label":"Sign in","to":"/login"}]'::jsonb, true, true),
('upload-music-video', 'Upload a music video', 'artist',
 'Every artist, including free accounts, can upload two music videos per calendar month. 1. Open Music videos. 2. Add your video file, title and details. 3. Publish — the video appears on your artist profile and the Videos page. If an upload fails, check the file finished uploading before leaving the page, then try again.',
 '[{"label":"Music videos","to":"/videos"},{"label":"Upload","to":"/upload"}]'::jsonb, true, true),
('payouts-stripe-connect', 'Payouts and connecting your bank', 'artist',
 'Payouts are handled through Stripe Connect on the Payouts and bank connection page in Settings. The page shows your real status: not connected, onboarding incomplete, verification pending, restricted, or ready. 1. Open Settings, then Payouts and bank connection. 2. Tap Connect your bank and finish the Stripe onboarding. 3. Return to the same page to see your balance and payout status. Exact percentages, dates and amounts are only ever shown on that page — never trust a chat answer for figures.',
 '[{"label":"Payouts and bank connection","to":"/settings/payouts"},{"label":"Host earnings","to":"/host-earnings"}]'::jsonb, true, true),
('admin-announcements', 'Make an announcement', 'admin',
 'Announcements are created from the admin Announcements page. 1. Open Admin dashboard, then Announcements. 2. Write the announcement and choose the audience. 3. Review it, then publish — publishing sends it to members, so double-check before confirming.',
 '[{"label":"Announcements (admin)","to":"/admin/announcements"},{"label":"Admin dashboard","to":"/admin"}]'::jsonb, true, true),
('admin-delete-account', 'Delete an account', 'admin',
 'Account deletion is permanent and removes the member''s access and content. Only admins can do it, from Manage accounts in the admin dashboard: find the account, review what will be removed, and confirm explicitly. If you are not an admin, you cannot delete other accounts — members manage their own account from Settings.',
 '[{"label":"Manage accounts (admin)","to":"/admin/users"},{"label":"Settings","to":"/settings"}]'::jsonb, true, true),
('blog-publishing', 'The Tunevio blog', 'everyone',
 'The Blog page has Tunevio''s published articles. New blog posts are published by Tunevio admins; members cannot create blog posts. If you have an article idea, send it through the Contact page.',
 '[{"label":"Blog","to":"/blog"},{"label":"Contact support","to":"/contact"}]'::jsonb, true, true),
('whats-new', 'What is new on Tunevio', 'everyone',
 'Platform news and announcements appear in your Notifications when you are signed in, and the newest music, artists and events are on the Home, Discover and Events pages.',
 '[{"label":"Notifications","to":"/notifications"},{"label":"Discover","to":"/discover"},{"label":"Events","to":"/events"}]'::jsonb, true, true),
('host-earnings-info', 'Host earnings', 'host',
 'Hosts can see their actual earnings, tier and payout status on the Host earnings page. Exact percentages and tier rules are configured by Tunevio admins and shown on that page — the assistant does not state figures it cannot verify.',
 '[{"label":"Host earnings","to":"/host-earnings"},{"label":"Payouts","to":"/payouts"}]'::jsonb, true, true),
('find-your-way', 'Find your way around Tunevio', 'everyone',
 'Main pages: Home for new music and artists, Discover and Search to find music, Charts and Leaderboard for rankings, Music videos for videos, Live now for live sessions, Play Arena for battles, Events for upcoming events, Store for artist merch, Library for your saved music, Messages for chats, and Settings for your account. Artists also have an Artist dashboard, Upload, Analytics and Earnings.',
 '[{"label":"Home","to":"/home"},{"label":"Discover","to":"/discover"},{"label":"Live now","to":"/live"},{"label":"Play Arena","to":"/play"}]'::jsonb, true, true)
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  audience = EXCLUDED.audience,
  body = EXCLUDED.body,
  links = EXCLUDED.links,
  confirmed = EXCLUDED.confirmed,
  published = EXCLUDED.published,
  updated_at = now();

UPDATE public.assistant_articles SET confirmed = true, updated_at = now() WHERE slug = 'the-host-role';